154	impl From<Value> for serde_json::Value {
155	    fn from(value: Value) -> Self {
156	        match value {
157	            Value::Null => serde_json::Value::Null,
158	            Value::Integer { value } => serde_json::Value::from(value),
159	            Value::Float { value } => serde_json::Value::from(value),
160	            Value::Text { value } => serde_json::Value::String(value),
161	            Value::Blob { value } => serde_json::Value::Object({
162	                let mut obj = serde_json::Map::new();
163	                let base64 = STANDARD_NO_PAD.encode(value);
164	                obj.insert("base64".to_string(), base64.into());
165	                obj
166	            }),
167	        }
168	    }
169	}
